// Ambil baris pertama yang belum dipublikasikan (ID POST kosong)
const rows = items.map(i => i.json);
const pending = rows.find(r => !r['ID POST'] || String(r['ID POST']).trim() === '');
if (!pending) return []; // tidak ada topik pending -> flow berhenti diam-diam
return [{ json: pending }];

// Ambil HTML challenge dari Get Proxy Challenge, ekstrak ciphertext
// CURRENT, lalu solve SlowAES (AES-128-CBC, no padding) -> cookie __test.
// Key & IV stabil; ciphertext ROTASI setiap challenge page.
const crypto = require('crypto');

const html = String($('Get Proxy Challenge').first().json.data || '');
const m = html.match(/toNumbers\("([0-9a-f]{32})"\)/g) || [];
// urutan: a=key, b=iv, c=ct
const hexes = m.map(x => x.replace(/^.*toNumbers\("/, '').replace(/"\)$/, ''));
if (hexes.length < 3) throw new Error('Challenge pattern tidak ditemukan di HTML');
const ct = Buffer.from(hexes[2], 'hex');
const key = Buffer.from(hexes[0], 'hex');
const iv = Buffer.from(hexes[1], 'hex');

const d = crypto.createDecipheriv('aes-128-cbc', key, iv);
d.setAutoPadding(false);
const cookieVal = Buffer.concat([d.update(ct), d.final()]).toString('hex');
const ua = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36';
return [{ json: { cookie: '__test=' + cookieVal, ua: ua } }];

const row = $('Select Topic').first().json;
const topic = String(row['PROMPT'] || row.TITLE || '').trim();
const keyword = String(row['TERGET KEYWORD'] || '').trim();
const category = String(row.KATEGORI || '').trim();
const sheetTitle = String(row.TITLE || '').trim();
const sheetImg = String(row.IMAGEGENERATOR || '').trim();

// slug deterministik dari topik -> idempotency antar run
const slug = (topic.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 180))
  || ('post-' + Date.now());

const system = `Kamu adalah content writer SEO profesional berbahasa Indonesia dengan standar E-E-A-T (Experience, Expertise, Authority, Trust) Google. Tugasmu menulis artikel blog 900-1050 kata berdasarkan topik, keyword, dan kategori yang diberikan. Niche situs: jasa pembuatan website, aplikasi custom, mentoring skripsi, jasa joki tugas, konsultasi IT untuk mahasiswa dan UMKM di Jambi, Indonesia.
Gaya: humanis, storytelling, kalimat bervariasi (pendek/sedang/panjang), sertakan data/statistik bila relevan, internal linking wajar. Struktur: hook pembuka kuat berisi keyword utama, overview bullet/numbering, minimal 3-5 section dengan heading <h2> dan sub-heading <h3>, bagian FAQ 3-5 pertanyaan, Call to Action natural di akhir.
OUTPUT: HANYA satu objek JSON valid, tanpa teks lain, TANPA markdown fences (jangan bungkus JSON dengan code fence), dengan skema:
{
  "title": "judul artikel",
  "excerpt": "ringkasan 1-2 kalimat",
  "content_html": "HTML lengkap artikel (h2/h3/p/ul/strong/em; jangan tambahkan <img>)",
  "focus_keyword": "keyword utama",
  "meta_description": "meta description 150-160 karakter",
  "tags": ["tag1", "tag2", "tag3"],
  "category": "Edukatif | Tips dan Rekomendasi | Studi Kasus | Perbandingan",
  "image_prompt": "deskripsi visual Bahasa Inggris untuk gambar artikel (subjek, suasana, gaya, warna)"
}
PENTING — VALIDITAS JSON (kegagalan paling sering):
- JANGAN SEKALI-KALI menggunakan karakter kutip ganda (") di dalam teks artikel. Gunakan tanda kutip tunggal '...' atau «...» untuk semua kutipan/kata yang ditegaskan. Jika tetap terlanjur memakai ", PASTIKAN di-escape sebagai \"

- Semua tanda kutip ganda DI DALAM nilai string (terutama content_html) WAJIB di-escape: \\"
- Untuk atribut HTML gunakan kutip tunggal (' ') atau JANGAN gunakan atribut sama sekali (cukup tag h2/h3/p/ul/li/strong/em tanpa atribut)
- Jangan gunakan karakter baris baru literal di dalam string JSON — gunakan \\n
- Untuk kutipan kalimat di dalam teks artikel gunakan tanda kutip '...' atau "..." yang di-escape, jangan tanda kutip miring
Konten harus faktual, tidak melebih-lebihkan, siap dipublikasikan.`;

const user = `Topik: ${topic}
Target keyword: ${keyword}
Kategori yang diminta: ${category}
Judul dari kalender konten (gunakan jika relevan): ${sheetTitle}

Tulis artikel sesuai instruksi sistem. Output JSON only.`;

const body = {
  model: 'no-think/kr/claude-haiku-4.5',
  stream: false,
  temperature: 0.7,
  max_tokens: 8000,
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: user }
  ]
};

return [{ json: { body_json: JSON.stringify(body), slug: slug, topic: topic, keyword: keyword, category: category, sheet_img_prompt: sheetImg } }];

const ai = items[0]?.json || {};
const raw = String(ai.choices?.[0]?.message?.content || '');
if (!raw) throw new Error('AI returned empty content');

let s = raw.replace(/```json\s*/i, '').replace(/```/g, '')
  .replace(/[\u0000-\u001F]/g, '')
  .replace(/[\u201C\u201D]/g, '"').replace(/[\u2018\u2019]/g, "'");

function extractBalancedJSON(str) {
  const first = str.indexOf('{');
  if (first === -1) return null;
  let inStr = false, esc = false, depth = 0;
  for (let i = first; i < str.length; i++) {
    const ch = str[i];
    if (esc) { esc = false; continue; }
    if (ch === '\\') { esc = true; continue; }
    if (ch === '"') { inStr = !inStr; continue; }
    if (!inStr) {
      if (ch === '{') depth++;
      else if (ch === '}') { depth--; if (depth === 0) return str.substring(first, i + 1); }
    }
  }
  return null;
}

const sub = extractBalancedJSON(s);
if (!sub) throw new Error('Balanced JSON tidak ditemukan. Raw: ' + raw.slice(0, 200));
let parsed;
try { parsed = JSON.parse(sub); }
catch (e) {
  // Tier 1: trailing comma, koma hilang antar objek/array, kontrol char
  let fixed = sub.replace(/,\s*([}\]])/g, '$1')
                 .replace(/}\s*{/g, '},{')
                 .replace(/\]\s*\[/g, '],[')
                 .replace(/[\u0000-\u001F]/g, '');
  try { parsed = JSON.parse(fixed); }
  catch (e2) {
    // Tier 2: escape kutip ganda tak-ter-escape di dalam nilai string
    // (heuristik: " ditutup hanya jika diikuti , } atau ])
    function escapeInnerQuotes(jt) {
      let out = '', inStr = false;
      for (let i = 0; i < jt.length; i++) {
        const ch = jt[i];
        if (!inStr) { out += ch; if (ch === '"') inStr = true; continue; }
        if (ch === '\\') { out += ch + (jt[i + 1] || ''); i++; continue; }
        if (ch === '"') {
          let j = i + 1;
          while (j < jt.length && jt[j] === ' ') j++;
          const nxt = jt[j];
          if (nxt === ',' || nxt === '}' || nxt === ']') { out += ch; inStr = false; }
          else { out += '\\' + ch; }
        } else { out += ch; }
      }
      return out;
    }
    try { parsed = JSON.parse(escapeInnerQuotes(fixed)); }
    catch (e3) {
      throw new Error('Gagal parse JSON: ' + e3.message +
        ' | near pos: ' + fixed.slice(Math.max(0, 4600), 5000));
    }
  }
}

const row = $('Select Topic').first().json;
const sheetImg = String(row.IMAGEGENERATOR || '').trim();
const fallbackImg = sheetImg || ('Ilustrasi modern tentang ' + String(row.PROMPT || 'teknologi'));

const title = String(parsed.title || row.TITLE || row.PROMPT || '').trim();
const tags = Array.isArray(parsed.tags) ? parsed.tags.filter(Boolean).slice(0, 8) : [];
const contentHtml = String(parsed.content_html || parsed.content || '').trim();
if (!title || !contentHtml) throw new Error('Parsed JSON kurang field title/content_html');

return [{
  json: {
    title: title,
    slug: $('Prepare AI Prompt').first().json.slug,
    excerpt: String(parsed.excerpt || '').trim(),
    content_html: contentHtml,
    focuskw: String(parsed.focus_keyword || row['TERGET KEYWORD'] || '').trim(),
    metadesc: String(parsed.meta_description || '').trim(),
    meta_title: title,
    tags: tags,
    category_name: String(parsed.category || '').trim(),
    image_prompt: String(parsed.image_prompt || fallbackImg).trim()
  }
}];

// Idempotency guard: response proxy (neverError) — 200 punya 'post', 404 punya 'error'
const g = items[0]?.json || {};
const found = g && g.post !== undefined;
return [{ json: { status: found ? 'exists' : 'new', found: !!found, guard_response: g } }];

const p = $('Parse & Structure').first().json;
const cats = ($('Fetch Categories').first().json.results || []);
const want = String(p.category_name || '').trim().toLowerCase();
const found = cats.find(c =>
  String(c.name || '').toLowerCase() === want || String(c.slug || '').toLowerCase() === want);
const categoryId = found ? found.id : 1;

// seed deterministik dari slug -> gambar sama jika workflow re-run
let seed = 0;
for (const ch of p.slug) seed = (seed * 31 + ch.charCodeAt(0)) >>> 0;
seed = (seed % 100000) || 1;

const imgPrompt = encodeURIComponent(p.image_prompt || 'blog article illustration');
const imageUrl = 'https://image.pollinations.ai/prompt/' + imgPrompt +
  '?width=1200&height=630&nologo=true&seed=' + seed + '&model=flux';
const imgHtml = '<img src="' + imageUrl + '" alt="' +
  String(p.title || '').replace(/"/g, '&quot;') + '" loading="lazy" />';

const payload = {
  title: p.title,
  slug: p.slug,
  content: imgHtml + '\n' + p.content_html,
  status: 'publish',
  type: 'post',
  excerpt: p.excerpt,
  categories: [categoryId],
  tags: p.tags
};

return [{ json: {
  publish_json: JSON.stringify(payload),
  category_id: categoryId,
  image_url: imageUrl,
  slug: p.slug,
  title: p.title
} }];

// Append JSONL ke /logs/blog-publisher-YYYY-MM.jsonl (fs via NODE_FUNCTION_ALLOW_BUILTIN)
const fs = require('fs');
const pub = ($('Publish Post').first().json.post) || {};
const parsed = $('Parse & Structure').first().json;
const row = {
  ts: $now.toISO(),
  action: 'published',
  slug: pub.slug || parsed.slug || '',
  title: pub.title || parsed.title || '',
  post_id: pub.id || '',
  url: pub.link || '',
  category_id: $('Assemble Payload').first().json.category_id || ''
};
const file = '/logs/blog-publisher-' + $now.toFormat('yyyy-MM') + '.jsonl';
fs.appendFileSync(file, JSON.stringify(row) + '\n', 'utf8');
return [{ json: { log_file: file, ...row } }];

