const row = {
  ts: $now.toISO(),
  action: 'skipped_existing',
  slug: parsed.slug || '',
  title: parsed.title || '',
  post_id: '',
  url: '',
  note: 'Slug sudah ada di WP \u2014 idempotency guard (jangan publish duplikat)'
};
const file = '/logs/blog-publisher-' + $now.toFormat('yyyy-MM') + '.jsonl';
fs.appendFileSync(file, JSON.stringify(row) + '\n', 'utf8');
return [{ json: { log_file: file, ...row } }];
